def number_of_ways(n: int, x: int) -> int:
    MOD = 10**9 + 7
    max_base = int(n ** (1.0 / x)) + 1
    powers = []
    for i in range(1, max_base + 1):
        p = i ** x
        if p <= n:
            powers.append(p)
        else:
