def permutation_difference(s: str, t: str) -> int:
    # Build a dictionary mapping each character to its index in s
    pos_s = {char: idx for idx, char in enumerate(s)}
    total = 0
    # Iterate over t, adding absolute index differences
    for idx, char in enumerate(t):
