from collections import Counter

def count_sub_multisets(nums, l, r):
    MOD = 10**9 + 7
    freq = Counter(nums)

    dp = [0] * (r + 1)
    dp[0] = 1

    for val, count in freq.items():
        for sum_val in range(r, -1, -1):
            if dp[sum_val] == 0:
                continue
            ways = dp[sum_val]
            for k in range(1, count + 1):
                new_sum = sum_val + k * val
                if new_sum > r:
                    break
                dp[new_sum] = (dp[new_sum] + ways) % MOD

    result = sum(dp[l:r+1]) % MOD
    return result
```

