from typing import List

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [1] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return
        if self.rank[rx] < self.rank[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    dsu = DSU(n)
    # map from prime to the first index having that prime
    prime_to_index = {}

    for i, val in enumerate(nums):
        if val == 1:
            return False  # 1 cannot connect to anything since gcd(1, x) = 1
        d = 2
        while d * d <= val:
            if val % d == 0:
                if d in prime_to_index:
                    dsu.union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                while val % d == 0:
                    val //= d
            d += 1 if d == 2 else 2  # skip even numbers after 2 for speed
        if val > 1:
            if val in prime_to_index:
                dsu.union(i, prime_to_index[val])
            else:
                prime_to_index[val] = i

    root = dsu.find(0)
    return all(dsu.find(i) == root for i in range(1, n))
