def maximumPrimeDistance(nums):
    """
    Returns the maximum distance between indices of two (not necessarily different)
    prime numbers in the given array.
    """
    # Helper to check primality for numbers up to 100
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        # Check odd divisors up to sqrt(num)
        # Since num <= 100, sqrt(100)=10
        for d in range(3, 11, 2):
            if d * d > num:
                break
            if num % d == 0:
                return False
        return True

    first = None
    last = None
    for i, val in enumerate(nums):
        if is_prime(val):
            if first is None:
                first = i
            last = i
    # At least one prime exists per constraints
    return last - first
