def maximum_jumps(nums, target):
    n = len(nums)

    @lru_cache(None)
    def dp(i):
        if i == n - 1:
            return 0
        max_jumps = -1
        for j in range(i + 1, n):
            if -target <= nums[j] - nums[i] <= target:
                sub = dp(j)
                if sub != -1:
                    max_jumps = max(max_jumps, 1 + sub)
